select

from ingestion_task
where id = #{taskId}
  and kb_id = #{kbId}

select

from ingestion_task
where created_by = #{createdBy}
  and client_request_id = #{clientRequestId}
limit 1

select

from ingestion_task
where kb_id = #{kbId}

  and status = #{status}

order by created_at desc, id desc
limit #{limit}

mapper.update:
update ingestion_task_item
set lease_until = timestampadd(second, #{leaseSeconds}, current_timestamp(6)),
    updated_at = current_timestamp(6)
where id = #{itemId}
  and execution_epoch = #{executionEpoch}
  and execution_stage = #{expectedExecutionStage}
  and stage_attempt = #{stageAttempt}
  and lease_token = #{leaseToken}
  and lease_until > current_timestamp(6)
  and status = 'RUNNING'

update ingestion_task_item
set parse_attempt = #{parseAttempt},
    docling_request_id = #{doclingRequestId},
    docling_job_id = #{doclingJobId},
    source_revision = #{sourceRevision},
    parse_request_snapshot = #{parseRequestSnapshot},
    updated_at = current_timestamp(6)
where id = #{itemId}
  and execution_epoch = #{executionEpoch}
  and execution_stage = #{expectedExecutionStage}
  and stage_attempt = #{stageAttempt}
  and lease_token = #{leaseToken}
  and status = 'RUNNING'
  and parse_attempt = #{parseAttempt}
  and (docling_request_id is null or docling_request_id = #{doclingRequestId})
  and (source_revision is null or source_revision = #{sourceRevision})
  and (
      parse_request_snapshot is null
      or parse_request_snapshot = cast(#{parseRequestSnapshot} as json)
  )

mapper.select:
select id
from ingestion_task_item
where id = #{itemId}
  and execution_epoch = #{executionEpoch}
  and execution_stage = #{expectedExecutionStage}
  and stage_attempt = #{stageAttempt}
  and lease_token = #{leaseToken}
  and status = 'RUNNING'
for update
